import * as React from 'react';
import { FaBriefcase, FaChartPie, FaPlusSquare, FaTasks, FaTachometerAlt } from 'react-icons/fa';
import {
  SidebarLayout,
  type SidebarNavItemConfig
} from '@hochhuth-consulting/hhhh-ui-library/HHHH-Sidebar';
import { clearSpaNavStack } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/spaNavigation';
import styles from './HhhhSpa.module.scss';

/**
 * Host adapter for shared HHHH-Sidebar.
 * - Does not modify hhhh-ui-library
 * - Keeps SPA nav stack clearing via hhhh-shared-ui
 * - Preserves existing Operations routes / labels / icons
 */
const SPA_SIDEBAR_ITEMS: SidebarNavItemConfig[] = [
  {
    id: 'team-portfolio',
    label: 'Team Portfolio',
    to: '/team-portfolio',
    section: 'Operations',
    icon: <FaBriefcase size={16} />
  },
  {
    id: 'project-overview',
    label: 'Project Overview',
    to: '/project-overview',
    section: 'Operations',
    icon: <FaChartPie size={16} />
  },
  {
    id: 'create-task',
    label: 'Create Task',
    to: '/create-task',
    section: 'Operations',
    icon: <FaPlusSquare size={16} />
  },
  {
    id: 'omt',
    label: 'OMT',
    to: '/omt',
    section: 'Operations',
    icon: <FaTasks size={16} />
  },
  {
    id: 'dashboard',
    label: 'Dashboard',
    to: '/dashboard',
    section: 'Operations',
    icon: <FaTachometerAlt size={16} />
  }
];

const logo = (
  <div
    className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-xs font-bold text-white"
    style={{ backgroundColor: 'var(--SiteColor)' }}
  >
    H
  </div>
);

export interface SpaLeftNavigationProps {
  children: React.ReactNode;
}

export default function SpaLeftNavigation(
  props: SpaLeftNavigationProps
): React.ReactElement {
  const onNavClick = React.useCallback((): void => {
    // Shared Sidebar clears URL search itself; host must clear the real SPA nav stack.
    clearSpaNavStack();
  }, []);

  return (
    <SidebarLayout
      items={SPA_SIDEBAR_ITEMS}
      header={{ logo, title: 'HHHH SPA' }}
      accentColor="var(--SiteColor)"
      ariaLabel="HHHH SPA navigation"
      defaultCollapsed={true}
      onNavClick={onNavClick}
      mainClassName={styles.hhhhSpaContent}
      mobileHeader={
        <span className="text-[15px] font-bold" style={{ color: 'var(--SiteColor)' }}>
          HHHH SPA
        </span>
      }
    >
      {props.children}
    </SidebarLayout>
  );
}

