import { spfi, SPFx as spSPFx } from "@pnp/sp";
import "@pnp/sp/webs";
import "@pnp/sp/lists";
import "@pnp/sp/search";

const normalizeUrl = (url: any): string =>
    (url || "").toString().toLowerCase().replace(/\/+$/, "");

// A metadata row is "visible" unless IsVisible is explicitly falsey (false / 0 / "0").
// Mirrors the previous drop condition so the pre-checked default matches what used to be shown.
const isMetaVisible = (meta: any): boolean =>
    !(meta?.IsVisible === false || meta?.IsVisible === 0 || meta?.IsVisible === "0");

/**
 * Build Sites filter UI from SmartMetadata (TaxType Sites / Sites Old).
 * Groups by Parent.Title (SP / IPPF / mbeon) — same shape as HHHHQA search path.
 */
export function buildActiveSitesFromMetadata(allRootMetaData: any[]): any[] {
    const siteItems = (allRootMetaData || []).filter((meta: any) => {
        if (!meta) return false;
        const tax = meta.TaxType;
        if (tax !== "Sites" && tax !== "Sites Old") return false;
        // Non-visible sites are now LISTED (unchecked by default) rather than dropped (q-nonvisible = show-unchecked).
        return Boolean(meta.listId && meta.Title);
    });

    const grouped: Record<string, any> = {};
    siteItems.forEach((meta: any) => {
        const groupTitle = meta?.Parent?.Title || meta?.siteName || meta?.Title || "Sites";
        const key = String(groupTitle).toLowerCase();
        const siteUrl = meta.originalSiteUrl || meta.siteUrl || "";
        if (!grouped[key]) {
            grouped[key] = {
                Site: {
                    Title: groupTitle,
                    Url: siteUrl,
                    SiteId: meta.SiteId || "",
                    WebId: meta.WebId || "",
                    IsVisible: false
                },
                TaskLists: [] as any[]
            };
        } else if (siteUrl && !grouped[key].Site.Url) {
            grouped[key].Site.Url = siteUrl;
        }

        // A site is visible (pre-checked by default) if any of its metadata rows is visible.
        if (isMetaVisible(meta)) grouped[key].Site.IsVisible = true;

        const already = grouped[key].TaskLists.some(
            (t: any) =>
                (t.Id && meta.listId && t.Id.toLowerCase() === meta.listId.toLowerCase()) ||
                (t.Title && meta.Title && t.Title.toLowerCase() === meta.Title.toLowerCase())
        );
        if (already) return;

        const coverObj =
            meta?.Item_x005F_x0020_Cover ||
            meta?.Item_x0020_Cover ||
            meta?.coverImage ||
            null;

        grouped[key].TaskLists.push({
            Title: meta.Title,
            Id: meta.listId,
            Url: siteUrl
                ? `${siteUrl.replace(/\/+$/, "")}/Lists/${encodeURIComponent(meta.Title)}`
                : "",
            Item_x005F_x0020_Cover: coverObj,
            Item_x0020_Cover: coverObj,
            coverImage: coverObj
        });
    });

    return Object.keys(grouped)
        .map((k) => grouped[k])
        .filter((g) => g.TaskLists?.length > 0);
}

async function getFilteredTaskLists(activeSites: any, allRootMetaData: any) {
    const result: any = [];
    activeSites?.forEach((siteObj: any) => {
        const siteUrlNorm = normalizeUrl(siteObj.Site?.Url);
        const matchingRootItems = (allRootMetaData || []).filter((meta: any) => {
            if (!meta) return false;
            const metaUrlNorm = normalizeUrl(meta.siteUrl || meta.originalSiteUrl);
            return Boolean(metaUrlNorm && siteUrlNorm && metaUrlNorm === siteUrlNorm);
        });

        if (!matchingRootItems.length) return;

        const matchedTaskLists: any = [];
        siteObj?.TaskLists?.forEach((taskList: any) => {
            const matchedMeta = matchingRootItems.find((meta: any) => {
                if (meta.listId && taskList.Id && meta.listId.toLowerCase() === String(taskList.Id).toLowerCase()) {
                    return true;
                }
                return Boolean(
                    meta.Title &&
                    taskList.Title &&
                    meta.Title.toLowerCase() === String(taskList.Title).toLowerCase()
                );
            });
            if (matchedMeta) {
                const coverObj =
                    matchedMeta.Item_x005F_x0020_Cover ||
                    matchedMeta.Item_x0020_Cover ||
                    matchedMeta.coverImage ||
                    null;
                matchedTaskLists.push({
                    ...taskList,
                    Item_x005F_x0020_Cover: coverObj,
                    Item_x0020_Cover: coverObj,
                    coverImage: coverObj
                });
            }
        });

        if (matchedTaskLists.length > 0) {
            // Join IsVisible from the matching metadata rows so the search path carries the flag too
            // (q-buildpath = both-enrich). Preserve any IsVisible already set upstream.
            const siteVisible = siteObj.Site?.IsVisible === true || matchingRootItems.some(isMetaVisible);
            result.push({
                Site: { ...siteObj.Site, IsVisible: siteVisible },
                TaskLists: matchedTaskLists
            });
        }
    });
    return result;
}

export async function getSubsitesForRoot({ spContext, AllRootMetaData }: any) {
    if (!spContext) {
        console.error("[FetchDynamicActiveSites] Missing SPFx context");
        return buildActiveSitesFromMetadata(AllRootMetaData);
    }

    const sp = spfi().using(spSPFx(spContext));
    const rawUrl =
        spContext?.pageContext?.web?.absoluteUrl ||
        (typeof window !== "undefined" ? window.location.href : "");
    const rootUrl = rawUrl
        ? rawUrl.match(/^(https?:\/\/[^\/]+\/sites\/[^\/\?#]+)/i)?.[1] ||
        rawUrl.replace(/\/+$/, "")
        : "https://hhhhteams.sharepoint.com/sites/HHHH";

    // Step 1: Get webs under the site collection (HHHHQA parity)
    let subsites: any[] = [];
    try {
        const subsiteResults = await sp.search({
            Querytext: `Path:${rootUrl}* contentclass:STS_Web`,
            RowLimit: 100,
            SelectProperties: ["Title", "Path", "SiteId", "WebId"]
        });
        subsites = (subsiteResults?.PrimarySearchResults || []).map((r: any) => ({
            Title: r.Title,
            Url: r.Path,
            SiteId: r.SiteId,
            WebId: r.WebId
        }));
    } catch (err) {
        console.error("[FetchDynamicActiveSites] Error searching subsites:", err);
    }

    // Also include unique siteUrls from Sites metadata (covers webs search may miss)
    const urlSet = new Set(subsites.map((s) => normalizeUrl(s.Url)));
    (AllRootMetaData || []).forEach((meta: any) => {
        if (
            (meta?.TaxType === "Sites" || meta?.TaxType === "Sites Old") &&
            meta?.siteUrl &&
            !urlSet.has(normalizeUrl(meta.siteUrl))
        ) {
            urlSet.add(normalizeUrl(meta.siteUrl));
            subsites.push({
                Title: meta?.Parent?.Title || meta?.siteName || meta?.Title,
                Url: meta.siteUrl,
                SiteId: "",
                WebId: ""
            });
        }
    });

    // Step 2: For each web, fetch Task lists (BaseTemplate 171 — HHHHQA parity)
    const siteTasks = await Promise.all(
        subsites.map(async (site) => {
            try {
                const siteSp = spfi(site.Url).using(spSPFx(spContext));
                const lists = await siteSp.web.lists();
                const taskLists = lists?.filter((l: any) => l.BaseTemplate === 171);
                const excludedTitles: string[] = [
                    "Offshore Tasks",
                    "Master Tasks",
                    "DRR",
                    "SDC Sites",
                    "QA",
                    "Foundation",
                    "Health",
                    "Gender",
                    "SP Online"
                ];
                const activeTaskList = taskLists?.filter(
                    (taskList: any) =>
                        taskList?.Title !== undefined && !excludedTitles.includes(taskList.Title)
                );
                // Enrich the search-built site with IsVisible joined from Sites metadata (q-buildpath = both-enrich).
                const siteUrlNorm = normalizeUrl(site.Url);
                const siteIsVisible = (AllRootMetaData || []).some(
                    (meta: any) =>
                        (meta?.TaxType === "Sites" || meta?.TaxType === "Sites Old") &&
                        normalizeUrl(meta.siteUrl || meta.originalSiteUrl) === siteUrlNorm &&
                        isMetaVisible(meta)
                );
                return {
                    Site: { ...site, IsVisible: siteIsVisible },
                    TaskLists: activeTaskList?.map((l: any) => ({
                        Title: l.Title,
                        Id: l.Id,
                        Url: `${site.Url}/Lists/${encodeURIComponent(l.Title)}`
                    }))
                };
            } catch (e) {
                console.log(`Error fetching lists for ${site.Url}`, e);
                return { Site: site, TaskLists: [] };
            }
        })
    );

    const AllRootSites = (AllRootMetaData || []).filter(
        (root: any) => root?.TaxType === "Sites" || root?.TaxType === "Sites Old"
    );
    const activesitesTasks = siteTasks?.filter((e) => e.TaskLists?.length > 0);
    let activeTAsklist = await getFilteredTaskLists(activesitesTasks, AllRootSites);

    // Prefer search+list path when it produced sites (HHHHQA behavior)
    if (activeTAsklist?.length > 0) {
        return activeTAsklist;
    }

    // Reliable fallback: SmartMetadata Sites grouped like the working QA UI
    const fromMeta = buildActiveSitesFromMetadata(AllRootMetaData);
    if (fromMeta.length > 0) {
        return fromMeta;
    }

    return activeTAsklist || [];
}

